import numpy as np
from collections import deque

def solve(inp):
    H,W=len(inp),len(inp[0])
    cnt=Counter(v for r in inp for v in r)
    bgc=max(cnt,key=cnt.get)
    seeds=[(r,c) for r in range(H) for c in range(W) if inp[r][c]!=bgc]
    reachable=set(seeds)
    q=deque(seeds)
    while q:
        r,c=q.popleft()
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                rr,cc=r+dr,c+dc
                if 0<=rr<H and 0<=cc<W and (rr,cc)!=q.qsize()*0 and (rr,cc) not in reachable:
                    reachable.add((rr,cc)); q.append((rr,cc))
    out=[row[:] for row in inp]
    for r in range(H):
        for c in range(W):
            if (r,c) not in reachable and inp[r][c]==bgc:
                out[r][c]=5
    return out

pred=solve(G['Demo pair 1 input'])
