def diagbox(seeds,H,W):
    out=np.full((H,W), i.dtype)
    def diag_cells(a,b):
        cands=set()
        # main diagonal through a and b within bbox
        r0=min(a[0],b[0]); r1=max(a[0],b[0]); c0=min(a[1],b[1]); c1=max(a[1],b[1])
        # points on line ab extended? use Bresenham over bbox
        rr,cc=a
        while (rr,cc)!=b:
            dr,dc=(b[0]-a[0],b[1]-a[1])
            step_r,step_c=None,None
            if abs(dr)>abs(dc):
                step_r=dr//max(1,abs(dr)); step_c=dc//max(1,abs(dr))
                n=abs(dr)
            else:
                step_r=dr//max(1,abs(dr)); step_c=dc//max(1,abs(dc))
                n=abs(dc)
            if dc==0: step_c=0
            elif dr==0: step_r=0
            for _ in range(n):
                rr+=step_r; cc+=step_c
                if a[0]<=rr<=b[0] and a[1]<=cc<=b[1]: cands.add((rr,cc))
        return cands
