    seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if cells & {(r,c)} and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); cur=[]
                while q:
                    y,x=q.popleft(); cur.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        n=(y+dy,x+dx)
                        if 0<=n[0]<H and 0<=n[1]<W and n in cells and n not in seen:
                            seen.add(n); q.append(n)
                out.append(cur)
    return out
print('comps:', [len(c) for c in comps(D8a,17,25)])

